lip.Get("id")).AsGodotDictionary();var selected=List(options,"clip_ids");if(selected.Count>0&&!selected.Contains(clip.Get("id")))continue;if(Text(options,"track_id").Length>0&&Text(track,"id")!=Text(options,"track_id"))continue;if(soloIds.Count>0&&!soloIds.Contains(Text(track,"id")))continue;if(Bool(values,"loop"))return Failure("FFmpeg is required for looped offline rendering.");if(Dict(values,"automation").Count>0)return Failure("FFmpeg is required for offline automation.");if(List(values,"effects").Count>0||List(track,"effects").Count>0||!Mathf.IsEqualApprox(clip.Get("playback_speed").AsDouble(),1)||!Mathf.IsEqualApprox(Number(values,"pitch",1),1))return Failure("FFmpeg is required for time/pitch processing and offline effects.");if(Bool(values,"muted")||Bool(track,"mute"))continue;var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",Get(values,"audio"),Variant.From(job)).As<AudioStream>();double clipDuration=clip.Get("duration").AsDouble(),clipStart=clip.Get("start_time").AsDouble();var decoded=cache.decode(stream,rate,clip.Get("source_offset").AsDouble(),clipDuration,120);if(Text(decoded,"error").Length>0)return Failure(Text(decoded,"error"));var samples=decoded["samples"].AsVector2Array();if(Bool(values,"reverse"))Array.Reverse(samples);double gain=Mathf.DbToLinear(Number(values,"volume_db")+Number(track,"volume_db")+Number(master,"volume_db",-3)),pan=Math.Clamp(Number(values,"pan")+Number(track,"pan"),-1,1);var balance=new Vector2((float)Math.Min(1,1-pan),(float)Math.Min(1,1+pan));double fadeIn=Math.Clamp(Number(values,"fade_in"),0,clipDuration),fadeOut=Math.Clamp(Number(values,"fade_out"),0,clipDuration);bool equalPower=Text(values,"fade_curve","linear")=="equal_power";int startFrame=(int)Math.Round(clipStart*rate,MidpointRounding.AwayFromZero);for(int frame=0;frame<samples.Length;frame++){int target=startFrame+frame;if(target>=output.Length)continue;double time=clipStart+(double)frame/rate,fade=1;if(fadeIn>0)fade=Math.Min(fade,Math.Clamp((time-clipStart)/fadeIn,0,1));if(fadeOut>0)fade=Math.Min(fade,Math.Clamp((clipStart+clipDuration-time)/fadeOut,0,1));if(equalPower)fade=Math.Sin(fade*Math.PI*.5);output[target]+=samples[frame]*(float)gain*balance*(float)fade;}job?.Call("update",(double)(index+1)/Math.Max(1,clips.Count),"Rendering WAV");}for(int index=0;index<output.Length;index++)output[index]=output[index].Clamp(new Vector2(-.966f,-.966f),new Vector2(.966f,.966f));int first=Math.Clamp((int)Math.Round(Number(options,"start")*rate,MidpointRounding.AwayFromZero),0,output.Length),last=Math.Clamp(first+(int)Math.Round(Number(options,"duration",duration-(double)first/rate)*rate,MidpointRounding.AwayFromZero),first,output.Length);if(last<=first)return Failure("The export range is empty.");output=output[first..last];duration=(double)output.Length/rate;using var wav=cache.to_wav(output,rate,!Bool(options,"mono"));string directory=NewDirectory();if(DirAccess.MakeDirRecursiveAbsolute(directory)!=Error.Ok)return Failure("Could not create WAV staging directory.");string temporary=directory.PathJoin("render.wav");var error=wav.SaveToWav(temporary);var result=error!=Error.Ok?Failure("Could not save WAV."):publish_complete(temporary,destination,job);if(Bool(result,"success")){result["path"]=destination;result["duration"]=duration;result["backend"]="bounded native PCM fallback";}return finish_process_files(result,directory);
